"""Saved-only RTC assessment and scientific figures; no native input access."""
import argparse,json
from pathlib import Path
import numpy as np
from point_additive_diagnostics import save_json

def read(p):return json.loads(Path(p).read_text())
def n(x):return 'unavailable' if x is None else f'{x:.4g}'
def report(root,dest):
    dest.mkdir(parents=True,exist_ok=True);d=root/'report';timing=read(d/'timing.json');support=read(d/'A/population-support.json');bands=read(d/'A/population-band-summary.json');coh=read(d/'A/population-coherence.json');responses=read(d/'A/source-responses.json');resource=read(d/'resources.json');events=read(d/'A/population-events.json');native=read(d/'A/native-source-accounting.json')
    groups={f:[r for r in timing if r['family']==f] for f in ('A','B')}
    def latency(f,key):
        a=[r[key] for r in groups[f]];return f'{np.median(a):.3f} [{min(a):.3f}, {max(a):.3f}]'
    def band(nw,stage,key='line_power',domain='all-stage-matched'):return next(r for r in bands if r['network']==nw and r['stage']==stage and r['metric']==key and r['domain']==domain)
    def medstage(f,key,nw=11):return float(np.median([next(z['seconds'] for z in next(q for q in r['networks'] if q['network']==nw)['intervals'] if z['stage']==key) for r in groups[f]]))
    def stotal(f,keys):return sum(medstage(f,key) for key in keys)
    export={f:medstage(f,'RTC_arrays_exported') for f in ('A','B')};rtc={f:float(np.median([r['networks'][0]['RTC_seconds'] for r in groups[f]])) for f in ('A','B')}
    minimum=min(r['RTC_fraction_of_exit_bounds'][0] for r in groups['A']);maximum=max(r['RTC_fraction_of_exit_bounds'][1] for r in groups['A']);cpu=[min(r['RTC_CPU_bounds'][0] for r in groups['A']),max(r['RTC_CPU_bounds'][1] for r in groups['A'])]
    lines=['# RTC cost, contamination and source response','','| Operation / target | Measured seconds | Before → RTC → PTC | Source / usable-support cost | Disposition |','|---|---:|---|---|---|',f'| RTC as a whole | A network11 median {rtc["A"]:.3f}; B {rtc["B"]:.3f}; workers overlap | Detailed audit below | Compact RTC projection gain0.996307; no injected support changes | Earns antialias/validity work; does not remove the11Hz line |',f'| Transient learning/review/support | {stotal("A",["spike_screen_complete","transient_assessment_complete","transient_support_decisions_complete"]):.3f} | 77/32 events;9/0 admitted shift groups;69888/93840 excluded pair cells | Source-near rejection remains diagnostically ambiguous | Completeness and false rejection not established here |',f'| Spectra, matched outcomes, reassessment | {stotal("A",["initial_spectra_complete","initial_learn_complete","post_notch_learned","post_notch_matched_outcome","post_lowpass_learned","post_lowpass_matched_outcome","relearning_complete"]):.3f} |11Hz power essentially unchanged by RTC; reduced by PTC, residual remains | No optional notch admitted in this acquisition | Consequential residual; next owner decision |',f'| Filter/application | {medstage("A","RTC_apply_complete"):.3f} |35–60Hz matched native band power falls by roughly10 orders of magnitude |307tap LPF; native finite support, factor2; boundary losses retained | Effective antialias filtering at measured scale |',f'| RTC arrays publication | A{export["A"]:.3f} → B{export["B"]:.3f} | Every binary payload and discrete choice exact | No scientific change | Retain B implementation efficiency; no measured end-to-end speedup |', '| Donor replacement / ringing | No replacements exercised | No manufactured pathological observation |0 replaced or replacement-influenced cells | Not established here |','', 'Seconds in operation rows are network11 medians from three runs, except stated counts; network12 is separately retained in timing.json. They are overlapping worker wall measurements, not additive end-to-end latency. CPU counters are process-wide.','', '## Latency and useful work','', '| Family | T5 published usable | Numerical analysis complete | Command exit | CPU seconds |','|---|---:|---:|---:|---:|']
    for f in ('A','B'):lines.append(f'| {f} | {latency(f,"ready")} | {latency(f,"analysis")} | {latency(f,"exit")} | {latency(f,"CPU")} |')
    cpu_gain=1-np.median([r['CPU'] for r in groups['B']])/np.median([r['CPU'] for r in groups['A']]);exit_delta=np.median([r['exit'] for r in groups['B']])-np.median([r['exit'] for r in groups['A']])
    lines += ['',f'A RTC occupies **{100*minimum:.2f}–{100*maximum:.2f}%** of actual command wall time across the defensible per-run clock bounds, about one sixth rather than one half. Network clocks are relative; timing.json preserves each lower/upper occupancy bound instead of inventing an exact union. The shared wrapper and worker durations bound unknown starts. RTC process-CPU bounds span {cpu[0]:.2f}–{cpu[1]:.2f} core-seconds. The upper envelope can include CAL on the early-finishing worker; no exclusive thread CPU is claimed.', '',f'B reduces median RTC-array publication by {export["A"]-export["B"]:.3f}s ({100*(1-export["B"]/export["A"]):.1f}%) in network11 and total command CPU by {100*cpu_gain:.2f}%. The median command exit is {exit_delta:+.3f}s relative to A, with overlapping ranges. **No end-to-end latency improvement is established.** CAL publication varies substantially and the remaining downstream/adapter work still dominates. B is retained as byte-preserving implementation efficiency, with source response inherited after three exact gates, not independently remeasured.', '', 'One workload at a time; two network workers, one feedback worker, one numerical-library thread. Fresh processes and original scientific state; OS cache not flushed and first-use observations retained. READY contains obtainable map/guard/measurement artifacts; caller50ms polling is separately stored. Required guard/noise/endpoint work and synchronous output remain included. Sampled process-tree RSS ranges are in timing.json; local Apple M4 Pro/two-network results do not extrapolate to Unity or all arrays. No operational deadline was invented.', '', '## Population audit','', '| Network | Full detectors / matched spectra | Native cells / RTC x available | CAL/PTC eligible entries |11Hz raw → RTC → M0 PTC → T5 residual median power |','|---|---:|---:|---:|---|']
    for r in support:
        nw=r['network'];vals=[band(nw,s)['detector_mean']['median'] for s in ('raw_native','RTC_native','PTC_M0','T5_residual')];lines.append(f'| {nw} | {r["detectors"]} / {sum(v>0 for v in r["complete_spectral_windows_per_detector"])} | {r["native_cells"]} / {r["RTC_x_available"]} | {sum(s["eligible_entries"] for s in r["segments"])} | '+ ' → '.join(n(v) for v in vals)+' |')
    lines += ['', 'Power units are (mJy/nominal beam)², integrated9.75–12.25Hz. Spectra use the accepted sample CAL multiplier,4s Hann windows, median centering,50% overlap, contiguous genuine support, and identical physical duration/resolution. The source exclusion is the own-REF M0 four-major-FWHM circle evaluated at actual detector pointings. CAL/PTC cadence is half native; comparison uses shared bins up to its Nyquist. Frequencies absent from the output grid are not called removed. Full-population support counts precede matched-window comparisons;69/80 detectors lack a usable calibrated/matched spectrum and are not hidden from denominators.', '']
    for r in support:
        nw=r['network'];raw=band(nw,'RTC_native');post=band(nw,'T5_residual');prom=band(nw,'RTC_native','line_prominence');after=band(nw,'T5_residual','line_prominence');c={v['stage']:v for v in coh if v['network']==nw};ev=[e for e in events if e['network']==nw];inside=sum(e['near_source'] is True for e in ev)
        lines += [f'Network{nw}: RTC11Hz band detector median/p95 is {n(raw["detector_mean"]["median"])}/{n(raw["detector_mean"]["p95"])}; T5 residual is {n(post["detector_mean"]["median"])}/{n(post["detector_mean"]["p95"])}. {100*prom["prominent_gt5_fraction"]:.1f}% of matched detector-windows have max line-bin/sideband-continuum >5 after RTC; {100*after["prominent_gt5_fraction"]:.1f}% after T5. This is a descriptive prominence criterion, not a new filter/admission threshold. Residual pair coherence median at the nearest11Hz bin is {c["RTC"]["median"]:.3f} in native RTC windows; matched output-window CAL/T5 medians are {c["CAL"]["median"]:.3f}/{c["T5_residual"]["median"]:.3f}. Pair counts, common-window distributions, detector persistence and segment variation are retained.',f'{inside}/{len(ev)} reviewed events have seed pointings inside the conservative source-exclusion circle. This does not prove false rejection: r is not an optically pure witness and no independent event truth is available. Source-injection branches induce zero state/center changes. Full source-near versus background retention, event classes and raw-scale adjacent-difference outliers near/away from boundaries are retained; flag counts alone are not validation of complete event detection.','']
    lines += ['The observed high-frequency native residual suppression and deterministic finite-support/tone/gap fixtures support antialias behavior. No donor replacement occurred. Physical gaps are respected by fixtures and the diagnostic window check; these observations have one native run each, so real pathological-gap/replacement treatment remains unestablished. Slow common residuals are not classified as atmospheric or electronic here. T5 input subtracts the actual m4 operand; cleaned residual and restored total are reported separately. They coincide on the chosen source-excluded windows, so feedback restoration is not being mistaken for returned contamination.', '', '## Source transfer and final measurement costs','', 'All three exact retained sky rasters enter raw x once, at native ALIGN-assigned timestamps, divided only by selected flxscale×CAL atmosphere. Calibration-only reconstruction error is ≤1.43×10⁻¹⁴mJy/beam. r and immutable input validity are unchanged. Each branch executes its own RTC learning; plans/masks/decisions are retained. Own-REF M0 noise is shared within the family. This starts at RTC, not optical/IQ/ALIGN validation or an adaptive-noise ensemble.', '', '| Branch | RTC spatial gain / relative error norm | T5 peak increment gain | T5 template gain | T5 aperture2 gain | T5 spatial gain / error norm |','|---|---|---:|---:|---:|---|']
    final=[r for r in responses if r['cycle']==5]
    for r in final:
        q={x['name']:x for x in r['measurement']['comparisons']};lines.append(f'| {r["branch"]} | {r["RTC_spatial"]["g"]:.6f} / {r["RTC_spatial"]["eta"]:.6f} | {q["peak"]["ratio"]:.6f} | {q["fixed_template"]["ratio"]:.6f} | {q["aperture_2"]["ratio"]:.6f} | {r["spatial"]["g"]:.6f} / {r["spatial"]["eta"]:.6f} |')
    lines += ['', 'RTC delta is projected through own-REF MAP coefficients/support; its optional fitted diagnostic adds that delta to REF M0 and is explicitly conditional, not an independently reduced RTC sky map. Ideal sky is native-projected without RTC/PTC attenuation and independently agrees with the containing-pixel raster control. HITS, NORMALIZATION and science support remain exact for these branches; ideal support is never redefined by injection losses.', '', '| T5 branch | Peak actual−ideal / own peak / σ | Pointing east,north discrepancy (arcsec) | Major,minor width discrepancy (arcsec) | Aperture2 discrepancy / σ |','|---|---|---|---|---|']
    effects=[]
    from point_response_cd import vector_measurement,MEASUREMENT_NAMES
    from report_point_rank import SIGMA,equivalent
    for r in final:
        q={x['name']:x for x in r['measurement']['comparisons']};ref=dict(zip(MEASUREMENT_NAMES,vector_measurement(r['measurement']['reference'])));sigma=r['endpoint_conditional_sigmas'];lines.append(f'| {r["branch"]} | {q["peak"]["absolute_discrepancy"]:.4f}mJy/beam / {100*q["peak"]["absolute_discrepancy"]/ref["peak"]:.4f}% / {q["peak"]["absolute_discrepancy"]/sigma["peak"]:.3f} | {q["east"]["absolute_discrepancy"]:.6f}, {q["north"]["absolute_discrepancy"]:.6f} | {q["FWHM_major"]["absolute_discrepancy"]:.6f}, {q["FWHM_minor"]["absolute_discrepancy"]:.6f} | {q["aperture_2"]["absolute_discrepancy"]:.2f} / {q["aperture_2"]["absolute_discrepancy"]/sigma["aperture2"]:.3f} |')
        for name,x in q.items():
            scale=sigma.get(SIGMA.get(name))
            eq,why=equivalent(scale,x['ratio'],r['spatial']['eta'],r['branch']) if name in ('peak','fixed_template','aperture_1','aperture_1p5','aperture_2') else (None,'no scalar response correction for position, shape or fitted background')
            effects.append(dict(branch=r['branch'],measurement=name,**x,own_REF=ref[name],fraction_of_full_source=x['absolute_discrepancy']/ref[name] if abs(ref[name])>1e-8 else None,conditional_sigma=scale,effect_over_sigma=x['absolute_discrepancy']/scale if scale else None,response_normalized_sigma=eq,normalization_scope=why))
    lines += ['', 'REF T5 conditional scales: peak6.164mJy/beam; east/north0.04049/0.03853arcsec; fitted width-axis scales0.04156/0.04686arcsec; fixed template7.898mJy/beam; aperture2 2744.34mJy/beam·arcsec². These are matching estimator scales, not paired significance or calibrated absolute sensitivity. Compact response-normalized scales are in effects.json only where supported; no maps are rescaled. The shoulder retains raw-aperture and fitted-constant contributions in source-responses.json and receives no scalar uncertainty correction. Large centroid/width *ratios* with nearly zero ideal increments are not meaningful gains; physical discrepancies above are the appropriate comparison. The approximately5% final-science goal is not imposed as a per-RTC threshold.', '', 'The prior post-RTC/CAL warm-T5 response measurements remain in postRTC-controls.json as downstream controls. They are not relabeled as RTC transfer. No PTC selection, extra cycle, or source-model change was made.', '', '## Outcome, limits and next action','', 'RTC earns its antialias, boundary and validity work at this measured scale, with a small measured compact/broad transfer cost. It does **not** earn credit for removing the consequential11Hz line: that feature survives RTC and still burdens PTC. Transient completeness/false rejection and donor replacement efficacy remain unestablished by this one observation. B demonstrates lower serialization/CPU work with identical science; whole-reduction latency remains about73s.', '', 'Keep warm-initialized fully re-solved observed-entry ALS rank10, cold M0 and exactly five applications as this development endpoint. m4 is the last applied model; m5 is recorded only. Preserve the cold rank10/T10 freeze and prior PCA/rank evidence. Retain B serialization as an implementation change only; source interpretation is inherited through exact equivalence. C is deliberately unselected, not failed.', '', '**Prioritized next action:** obtain the owner decision on exact detector applicability/admission of the already selected11.0062558446Hz,1Hz-width,approximately3s notch for POINT152430 networks11/12; then propose one fixed-design comparison through the same T5 endpoint. The historical coefficient selection expressly did not automatically admit every detector/cadence. No new threshold, width sweep, automatic follow-on or further PTC/FRUIT optimization is started.', '',f'Executed {resource["attempts"]["trajectory"]} trajectories, {resource["attempts"]["feedback"]} feedback applications and {resource["attempts"]["rtc_only"]} extra RTC-only capture; no replacement trajectories. The initial FITS whole-file comparator stop is preserved: sealed historical T2/T4 bytes established checksum metadata differences and exact science, permitting continuation without rerun. Native error-level message count is zero. Numerical-library warnings are retained; all six A saved uncertainty operators/scales were independently reproduced exactly without the warned BLAS contraction, and B endpoint records match A exactly.', '',f'Campaign footprint before compact preservation {resource["actual_campaign_bytes_before_compaction"]/1e9:.3f}GB against20GB ceiling. Native write volume, reservations, attempt logs and compact/cleanup manifests are distinct records. Saved-only reporting and final independent review precede deletion of exact enumerated campaign payloads; original/tune/APT/calibration/frozen profile dependencies are protected. Supplemental AppleClang/Homebrew evidence only; no Unity run, transfer, push, merge or production activation.']
    lines += ['', '![Full-population matched spectra](population-spectra.png)', '', '![Source response discrepancies with row-shared scales](source-response-residuals.png)', '', 'The figure branch names beginning C- identify retained control rasters; they are A-family response branches, not an executed policy family C. See [reproduction and evidence index](REPRODUCTION.md).']
    # Improve prose spacing without changing identifiers or machine-readable records.
    for old,new in [('network11','network 11'),('network12','network 12'),('Network11','Network 11'),('Network12','Network 12'),('the11Hz','the 11 Hz'),('11Hz','11 Hz'),('35–60Hz','35–60 Hz'),('gain0.','gain 0.'),('approximately5%','approximately 5%'),('about73s','about 73 s'),('caller50ms','caller 50 ms'),('against20GB','against 20 GB'),('selected11.','selected 11.'),('networks11/12','networks 11/12'),('rank10','rank 10')]:
        lines=[line.replace(old,new) for line in lines]
    (dest/'ASSESSMENT.md').write_text('\n'.join(lines)+'\n');save_json(dest/'effects.json',effects);save_json(dest/'report-facts.json',dict(timing=timing,RTC_array_export_medians=export,RTC_network11_medians=rtc,CPU_fraction_saved=cpu_gain,exit_median_delta=exit_delta,source_effects=effects,resources=resource))
    figures(d,dest)

def figures(d,dest):
    import matplotlib;matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    z=np.load(d/'A/population-spectra.npz');sup=read(d/'A/population-support.json');fig,axs=plt.subplots(2,2,figsize=(11,7),layout='constrained')
    for col,nw in enumerate((11,12)):
        for stage in ('raw','RTC'):
            a=z[f'n{nw}_{stage}'];axs[0,col].semilogy(z['native_frequency'][1:],np.nanmedian(a,axis=1)[1:],label=stage)
        for stage in ('raw_native','RTC_native','PTC_M0','T5_residual'):
            entries=next(s for s in sup if s['network']==nw)['segments'];total=np.zeros_like(z[f'n{nw}_s{entries[0]["segment"]}_{stage}']);count=np.zeros(total.shape[1])
            for s in entries:
                w=np.asarray(s['windows_by_full_population']);a=z[f'n{nw}_s{s["segment"]}_{stage}'];total+=np.nan_to_num(a)*w[None,:];count+=w
            a=np.divide(total,count[None,:],out=np.full_like(total,np.nan),where=count[None,:]>0);axs[1,col].semilogy(z['output_frequency'][1:],np.nanmedian(a,axis=1)[1:],label=stage)
        axs[0,col].set(title=f'Network {nw}: native matched support',xlabel='Hz',ylabel='Median detector PSD (mJy²/beam²/Hz)');axs[1,col].set(title=f'Network {nw}: all-stage matched windows',xlabel='Hz',ylabel='Median detector PSD (mJy²/beam²/Hz)')
        for ax in axs[:,col]:ax.axvspan(9.75,12.25,color='gray',alpha=.15);ax.grid(alpha=.2);ax.legend(fontsize=8)
    fig.savefig(dest/'population-spectra.png',dpi=160);plt.close(fig)
    z=np.load(d/'A/response-maps.npz');fig,axs=plt.subplots(2,3,figsize=(11,7),layout='constrained');branches=('C-core-plus','C-core-minus','C-shoulder')
    for i,k in enumerate((0,5)):
        limit=max(np.max(abs(z[f'{b}_T{k}_residual'])) for b in branches)
        for j,b in enumerate(branches):
            im=axs[i,j].imshow(z[f'{b}_T{k}_residual'],origin='lower',extent=(41,-41,-41,41),cmap='RdBu_r',vmin=-limit,vmax=limit);axs[i,j].set(title=f'{b}, '+('M0' if k==0 else 'T5'),xlabel='East (arcsec)',ylabel='North (arcsec)')
        fig.colorbar(im,ax=axs[i,:].tolist(),label='Actual − own REF − ideal (mJy/beam)',shrink=.8)
    fig.savefig(dest/'source-response-residuals.png',dpi=160);plt.close(fig)

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();report(a.root,a.output)
